import{bQ as t,aL as d,u as o,G as n}from"./chunks/framework.igrrHzX3.js";const s="/knowledge/images/ingestion-job-overwiew.svg",a="/knowledge/images/ingestion-job-pipeline.svg",i="/knowledge/images/ingestion-job-sequence-diagram.svg",c="/knowledge/images/ingestion-job-chunking.svg",u=JSON.parse('{"title":"Ingestion job","description":"","frontmatter":{},"headers":[],"relativePath":"guides/components/ingestion-job.md","filePath":"guides/components/ingestion-job.md"}'),r={name:"guides/components/ingestion-job.md"};function l(p,e,h,g,m,_){return d(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="ingestion-job" tabindex="-1">Ingestion job <a class="header-anchor" href="#ingestion-job" aria-label="Permalink to &quot;Ingestion job&quot;">​</a></h1><p>The ingestion job <strong>builds and maintains the index</strong>. Each run clones the Kalisio repositories, finds the files worth indexing, cuts the ones that changed into chunks, embeds them and writes them to <a href="/knowledge/guides/components/qdrant.html">Qdrant</a>.</p><p><img src="'+s+`" alt="Ingestion job"></p><details class="details custom-block"><summary>Module Structure</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ingestion/</span></span>
<span class="line"><span>├── bin.py                    entry point: configure logging, run(), exit code</span></span>
<span class="line"><span>├── main.py                   run(): the seven steps, timed and logged</span></span>
<span class="line"><span>├── config.py                 Config: every setting, from the environment</span></span>
<span class="line"><span>├── logger.py                 the &quot;knowledge&quot; logger, step() timer, durations</span></span>
<span class="line"><span>├── pipeline/</span></span>
<span class="line"><span>│   ├── workspace_clone.py      step 3 · link the tooling, run k-clone</span></span>
<span class="line"><span>│   ├── workspace_scanner.py    step 4 · find repositories, git ls-files, filters</span></span>
<span class="line"><span>│   └── change_detection.py     steps 4-5 · file keys, SHA-1 digests, what changed</span></span>
<span class="line"><span>├── chunkers/                 step 5 · one chunker per format, see File formats</span></span>
<span class="line"><span>└── clients/</span></span>
<span class="line"><span>    ├── embeddings.py           step 6 · chunks → vectors (sentence-transformers)</span></span>
<span class="line"><span>    └── vectordb.py             every Qdrant read and write of the job</span></span></code></pre></div></details><h2 id="pipeline-d-ingestion" tabindex="-1">Pipeline d&#39;ingestion <a class="header-anchor" href="#pipeline-d-ingestion" aria-label="Permalink to &quot;Pipeline d&#39;ingestion&quot;">​</a></h2><p align="center"><img src="`+a+'" alt="Pipeline d&#39;ingestion"></p><div class="tip custom-block"><p class="custom-block-title">sequence diagram</p><p><img src="'+i+'" alt="sequence diagram"></p></div><div class="info custom-block"><p class="custom-block-title">Step 5: Chunking the files that changed</p><p>A file is reindexed when its key is new, or when its digest differs from the indexed one:</p><p><img src="'+c+'" alt="Step 5: Chunking the files that changed"></p></div><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><p><strong>Required</strong></p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>QDRANT_URL</code></td><td>Qdrant REST endpoint, e.g. <code>http://qdrant:6333</code></td></tr><tr><td><code>QDRANT_COLLECTION_CODE</code></td><td>collection of the chunks, e.g. <code>kalisio_code</code>, the API reads the same</td></tr><tr><td><code>QDRANT_COLLECTION_METADATA</code></td><td>collection of the run record, e.g. <code>knowledge_metadata</code></td></tr><tr><td><code>EMBEDDING_MODEL</code></td><td>sentence-transformers model, e.g. <code>Qwen/Qwen3-Embedding-0.6B</code>, the API must use the same</td></tr><tr><td><code>DEVELOPMENT_DIR</code></td><td>the workspace root: one directory per organisation</td></tr></tbody></table><p><strong>Workspace and cloning</strong></p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>KLI_ORGANIZATION</code></td><td><code>kalisio</code></td><td>organisation passed to <code>k-clone</code> (<code>kalisio</code>, <code>irsn</code>, <code>airbus</code>)</td></tr><tr><td><code>KLI_WORKSPACE</code></td><td><code>apps</code></td><td>kli workspace to clone (<code>apps</code>, <code>libs</code>, <code>services</code>, ..., <code>all</code>)</td></tr><tr><td><code>KALISIO_DEVELOPMENT_DIR</code></td><td><code>$DEVELOPMENT_DIR/kalisio</code></td><td>where <code>k-clone</code> finds the tooling and clones the Kalisio repositories</td></tr><tr><td><code>INDEXED_REPOSITORIES</code></td><td><em>(all)</em></td><td>comma-separated repository names to scan; a name not on disk is skipped</td></tr><tr><td><code>KALISIO_GITHUB_TOKEN</code></td><td>,</td><td>token k-clone clones GitHub repositories with; without it, ssh (needs a key in the container)</td></tr><tr><td><code>GITLAB_IRSN_TOKEN</code></td><td>,</td><td>same, for an IRSN workspace on GitLab</td></tr><tr><td><code>KALISIO_GITHUB_URL</code> · <code>GITLAB_IRSN_URL</code></td><td><em>(built from the tokens)</em></td><td>an explicit clone URL wins over the token</td></tr><tr><td><code>KALISIO_TOOLING_DIR</code></td><td><code>/opt/kalisio</code></td><td>where the image installs <code>development</code> and <code>kli</code></td></tr></tbody></table><p><strong>Scanning</strong></p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>SUPPORTED_FILE_EXTENSIONS</code></td><td><code>md,js,mjs,cjs,vue,json,yaml,yml,gotmpl,sh</code></td><td>extensions to index</td></tr><tr><td><code>MAX_FILE_SIZE</code></td><td><code>100000</code></td><td>bytes; larger files are skipped</td></tr><tr><td><code>IGNORED_DIRECTORIES</code></td><td><code>.git,node_modules,dist,build,coverage,.vscode,...</code></td><td>directory names never scanned (<code>.github</code> is <em>not</em> ignored: it holds the CI workflows)</td></tr><tr><td><code>IGNORED_FILENAMES</code></td><td><code>package.json,package-lock.json,pnpm-lock.yaml,CHANGELOG.md,...</code></td><td>file names never indexed</td></tr><tr><td><code>IGNORED_FILE_PATTERN</code></td><td><code>\\.(min|bundle|chunk)\\.\\w+$|-lock\\.(json|yaml)$|\\.(enc|dec)\\.\\w+$</code></td><td>regex on file names: minified bundles, lock files, SOPS secrets</td></tr></tbody></table><p><strong>Chunking and embedding</strong></p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>CHUNK_SIZE</code> · <code>CHUNK_OVERLAP</code></td><td><code>500</code> · <code>80</code></td><td>prose: Markdown, JSON, YAML</td></tr><tr><td><code>CODE_CHUNK_SIZE</code> · <code>CODE_CHUNK_OVERLAP</code></td><td><code>800</code> · <code>120</code></td><td>code: JavaScript, Vue, shell</td></tr><tr><td><code>EMBEDDING_BATCH_SIZE</code></td><td><code>8</code></td><td>chunks per forward pass of the model</td></tr></tbody></table><p><strong>Qdrant details</strong></p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>QDRANT_VECTOR_SIZE_COLLECTION_CODE</code></td><td><code>1024</code></td><td>dimension of the chunk vectors, the model&#39;s</td></tr><tr><td><code>QDRANT_VECTOR_COLLECTION_METADATA</code></td><td><code>1</code></td><td>dimension of the dummy vectors of the bookkeeping collections</td></tr><tr><td><code>QDRANT_COLLECTION_FILES</code></td><td><code>&lt;QDRANT_COLLECTION_CODE&gt;_files</code></td><td>collection of the file entries</td></tr><tr><td><code>QDRANT_LAST_INGESTION_KEY</code></td><td><code>last_ingestion</code></td><td>payload key of the run timestamp</td></tr><tr><td><code>LOG_LEVEL</code></td><td><code>INFO</code></td><td><code>DEBUG</code> also logs every dropped file</td></tr></tbody></table>',19)])])}const E=t(r,[["render",l]]);export{u as __pageData,E as default};
